window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b973ea3b4669226a"]={"versions": [{"id": "FIG-b973ea3b4669226a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation regelbasierter numerischer Werte (NumericalRuleBasedValueSpecification) innerhalb des AUTOSAR-SoftwareComponentTemplate (Metamodell-Ausschnitt zur ValueSpecification). Es beschreibt die strukturellen Elemente zur deklarativen, regelgestützten Wertebelegung inklusive Variabilitätsunterstützung auf Metamodell-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>NumericalRuleBasedValueSpecification</code> (spezialisiert bzw. abgeleitet von der abstrakten Klasse <code>AbstractRuleBasedValueSpecification</code>): Bildet den Wurzelknoten der Spezifikation.\n</li><li>Aggregation <code>ruleBasedValues</code> [1]: Bindet eine Instanz von <code>RuleBasedValueSpecification</code> ein.\n</li><li><code>RuleBasedValueSpecification</code>: Besitzt das Attribut <code>+ rule :Identifier</code>.\n</li><li>Aggregation <code>arguments</code> [1] (stereotypisiert als <code>«atpVariation»</code>): Komposition von <code>RuleBasedValueSpecification</code> zu <code>RuleArguments</code>.\n</li><li><code>«atpMixed» RuleArguments</code>: Enthält die Attribute <code>+ v :Numerical [0..1]</code>, <code>+ vt :VerbatimString [0..1]</code> sowie das variabilitätsbehaftete Attribut <code>«atpVariation» + vf :Numerical [0..1]</code>.\n</li><li>Aggregation <code>vtf</code> [0..1] (stereotypisiert als <code>«atpVariation»</code>): Komposition von <code>RuleArguments</code> zu <code>NumericalOrText</code>.\n</li><li><code>NumericalOrText</code>: Enthält die Attribute <code>+ vt :String [0..1]</code> und <code>«atpVariation» + vf :Numerical [0..1]</code>.\n</li><li>Notiz-Element <code>«atpVariation» Tags: vh.latestBindingTime = preCompileTime</code>: Bezieht sich per gestrichelter Assoziationslinie auf die Variabilitätspunkte (<code>«atpVariation»</code>) der Kompositionen und Attribute.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Sequenz- oder Laufzeitablauf dargestellt. Die Auswertung der Regeln und Parameterwerte erfolgt typischerweise tooling-gestützt während der Modellierungs- oder Codegenerierungsphase (spätestens zur <code>preCompileTime</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Generatoren und Modellierungs-Werkzeuge zur Definition von Initialisierungs- oder Vorgabewerten via Regeln. Variabilitätspunkte an den Aggregationen und Attributen (<code>«atpVariation»</code>) müssen spätestens zur Vorkompilierzeit (<code>vh.latestBindingTime = preCompileTime</code>) aufgelöst werden. Die Stereotypisierung <code>«atpMixed»</code> bei <code>RuleArguments</code> erlaubt gemischte Inhaltsmodelle in der XML-Serialisierung.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fb28e425e16b95ed", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation regelbasierter numerischer Werte (NumericalRuleBasedValueSpecification) innerhalb des AUTOSAR-SoftwareComponentTemplate (Metamodell-Ausschnitt zur ValueSpecification). Es beschreibt die strukturellen Elemente zur deklarativen, regelgestützten Wertebelegung inklusive Variabilitätsunterstützung auf Metamodell-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>NumericalRuleBasedValueSpecification</code> (spezialisiert bzw. abgeleitet von der abstrakten Klasse <code>AbstractRuleBasedValueSpecification</code>): Bildet den Wurzelknoten der Spezifikation.\n</li><li>Aggregation <code>ruleBasedValues</code> [1]: Bindet eine Instanz von <code>RuleBasedValueSpecification</code> ein.\n</li><li><code>RuleBasedValueSpecification</code>: Besitzt die Attribute <code>+ maxSizeToFill :Integer [0..1]</code> und <code>+ rule :Identifier</code>.\n</li><li>Aggregation <code>arguments</code> [1] (stereotypisiert als <code>«atpVariation»</code>): Komposition von <code>RuleBasedValueSpecification</code> zu <code>RuleArguments</code>.\n</li><li><code>«atpMixed» RuleArguments</code>: Enthält die Attribute <code>+ v :Numerical [0..1]</code>, <code>+ vt :VerbatimString [0..1]</code> sowie das variabilitätsbehaftete Attribut <code>«atpVariation» + vf :Numerical [0..1]</code>.\n</li><li>Aggregation <code>vtf</code> [0..1] (stereotypisiert als <code>«atpVariation»</code>): Komposition von <code>RuleArguments</code> zu <code>NumericalOrText</code>.\n</li><li><code>NumericalOrText</code>: Enthält die Attribute <code>+ vt :String [0..1]</code> und <code>«atpVariation» + vf :Numerical [0..1]</code>.\n</li><li>Notiz-Element <code>«atpVariation» Tags: vh.latestBindingTime = preCompileTime</code>: Bezieht sich per gestrichelter Assoziationslinie auf die Variabilitätspunkte (<code>«atpVariation»</code>) der Kompositionen und Attribute.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Sequenz- oder Laufzeitablauf dargestellt. Die Auswertung der Regeln und Parameterwerte erfolgt typischerweise tooling-gestützt während der Modellierungs- oder Codegenerierungsphase (spätestens zur <code>preCompileTime</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Generatoren und Modellierungs-Werkzeuge zur Definition von Initialisierungs- oder Vorgabewerten via Regeln. Über <code>maxSizeToFill</code> kann die Maximalgröße für die regelbasierte Befüllung numerischer Strukturen spezifiziert werden. Variabilitätspunkte an den Aggregationen und Attributen (<code>«atpVariation»</code>) müssen spätestens zur Vorkompilierzeit (<code>vh.latestBindingTime = preCompileTime</code>) aufgelöst werden. Die Stereotypisierung <code>«atpMixed»</code> bei <code>RuleArguments</code> erlaubt gemischte Inhaltsmodelle in der XML-Serialisierung.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b973ea3b4669226a", "to": "FIG-fb28e425e16b95ed", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In Klasse <code>RuleBasedValueSpecification</code> wurde das optionale Attribut <code>maxSizeToFill :Integer [0..1]</code> hinzugefügt.\n</li></ul>"}]};
